Setting it up on VsCode
To give suggestions on the fly, I use the Ruff VsCode Extension.
Besides that, I have my settings.json with my personal preferences:
// Use Ruff as the default formatter for Python files
"[python]": {
"editor.defaultFormatter": "charliermarsh.ruff",
"editor.codeActionsOnSave": {
    "source.fixAll": "explicit",
    "source.organizeImports": "explicit"
}
},
// Formatter for notebook cells
"[jupyter]": {
"editor.defaultFormatter": "charliermarsh.ruff"
},
// Enable format on save for notebooks
"notebook.formatOnSave.enabled": true,
"editor.formatOnSave": true,
But these are only global settings in my personal environment.
Working with others on the same project can be painful if you don’t have a default formatter (because other team members can have different formatters and specifications); as a result, code may change the formatting for a new user. Therefore, having a .vscode/settings.json inside of the folder of your project guarantees that everyone will use the same formatter. For that, just copy your personal settings to .vscode/settings.json.
I also make Ruff as a default extension in .vscode/extensions.json:
{
    "recommendations": [
        "charliermarsh.ruff"
    ]
}
Last but not least, you can also install ruff in your environment and implement it on your CI/CD routines. But it will not be covered here. Installing the extension and using the .vscode/settings.json guarantees that the suggestions will be made on the fly. But it depends on your IDE and that everyone from your team uses it.

dados = FileAttachment("../dados/brasileiro.json").json()

edicoes = dados.edicoes

linhas = {
  const colunas = dados.linhas;
  const nomes = Object.keys(colunas);
  return colunas.ano.map((_, i) =&gt; Object.fromEntries(nomes.map((k) =&gt; [k, colunas[k][i]])));
}

// Eixo do tempo: as edições e também os anos sem campeonato (2020 e 2021), que ficam em branco
linhaDoTempo = [...edicoes, ...dados.sem_campeonato].sort((a, b) =&gt; a.ano - b.ano)
rotulos = linhaDoTempo.map((e) =&gt; e.rotulo)
edicaoDoAno = new Map(edicoes.map((e) =&gt; [e.ano, e]))
ultimoAno = d3.max(edicoes, (e) =&gt; e.ano)
categorias = ["Adulto", "Master", "Sub-18", "Sub-15"]
ufsPrincipais = ["SP", "PR", "RJ", "PE", "SC", "RS", "GO"]
num = (x, casas = 0) =&gt; x.toLocaleString("pt-BR", {minimumFractionDigits: casas, maximumFractionDigits: casas})
pct = (x) =&gt; num(100 * x, 1) + "%"
rotuloBotonista = (b) =&gt; `${b.nome} (${b.ufo ?? "sem UF"})`

// Recortes que dependem do filtro geral
categoriasDoFiltro = ({"Todas": categorias, "Sub-15 + Sub-18": ["Sub-18", "Sub-15"]})[categoria] ?? [categoria]
linhasCat = linhas.filter((d) =&gt; categoriasDoFiltro.includes(d.cat))
variasCategorias = categoriasDoFiltro.length &gt; 1
textoCategoria = categoria === "Todas" ? "todas as categorias"
  : categoria === "Sub-15 + Sub-18" ? "as categorias Sub-15 e Sub-18 somadas"
  : `a categoria ${categoria}`

function grafico(opcoes, {largo = false} = {}) {
  const figura = Plot.plot({
    width: largo ? Math.max(width, 780) : Math.min(width, 760),
    style: {fontSize: "11px", background: "transparent", overflow: "visible"},
    opacity: {type: "identity"},
    ...opcoes
  });
  return html`&lt;div class="fm-rolagem ${largo ? "fm-largo" : ""}"&gt;${figura}&lt;/div&gt;`;
}

dica = ({fill: "var(--fm-superficie)", stroke: "var(--fm-suave)", fontSize: 12, lineHeight: 1.25})

eixoEdicoes = ({type: "band", domain: rotulos, label: null, tickRotate: -55, tickSize: 3, padding: 0.18})

// Eixo só com os anos a partir do primeiro que tem o dado (evita metade do gráfico vazia)
function eixoAPartirDe(rotulosComDado) {
  const inicio = d3.min(rotulosComDado, (r) =&gt; rotulos.indexOf(r)) ?? 0;
  return {...eixoEdicoes, domain: rotulos.slice(inicio)};
}

function empilhar(registros, chaveGrupo, dominio) {
  return d3.rollups(registros, (v) =&gt; v.length, (d) =&gt; d.ano, chaveGrupo)
    .flatMap(([ano, grupos]) =&gt; {
      const edicao = edicaoDoAno.get(ano);
      const total = d3.sum(grupos, (g) =&gt; g[1]);
      return grupos.map(([grupo, n]) =&gt; ({ano, rotulo: edicao.rotulo, parcial: edicao.parcial, grupo, n, total}));
    })
    .sort((a, b) =&gt; a.ano - b.ano || dominio.indexOf(a.grupo) - dominio.indexOf(b.grupo));
}

function barrasEmpilhadas(registros, dominio, cores, rotuloY) {
  return grafico({
    height: 430, marginBottom: 150, marginLeft: 64, marginTop: 24,
    x: eixoEdicoes,
    y: {label: rotuloY, grid: true},
    color: {domain: dominio, range: cores, legend: true},
    marks: [
      Plot.barY(registros, {
        x: "rotulo", y: "n", fill: "grupo", order: null,
        fillOpacity: (d) =&gt; (d.parcial ? 0.45 : 1),
        insetTop: 1, tip: dica,
        title: (d) =&gt; `${d.rotulo}\n${d.grupo}: ${num(d.n)}\nTotal: ${num(d.total)}${d.parcial ? "\nClassificação publicada só em parte" : ""}`
      }),
      Plot.ruleY([0])
    ]
  }, {largo: true});
}

function carreiras(registros) {
  return d3.rollups(registros, (v) =&gt; {
    const anos = [...new Set(v.map((d) =&gt; d.ano))].sort(d3.ascending);
    return {id: v[0].id, nome: v[0].nome, ufo: v[0].ufo, anos, n: anos.length, sequencia: maiorSequencia(anos)};
  }, (d) =&gt; d.id).map((d) =&gt; d[1]);
}

// Maior sequência de edições seguidas. Edições com classificação parcial não interrompem a
// sequência (o botonista pode ter jogado sem aparecer na lista), mas só contam se ele aparece.
function maiorSequencia(anos) {
  const presente = new Set(anos);
  let melhor = {n: 0}, atual = null;
  for (const e of edicoes) {
    if (presente.has(e.ano)) {
      atual = atual ? {n: atual.n + 1, inicio: atual.inicio, fim: e.ano} : {n: 1, inicio: e.ano, fim: e.ano};
      if (atual.n &gt; melhor.n) melhor = atual;
    } else if (!e.parcial) atual = null;
  }
  return melhor;
}

function top10(lista, valor) {
  const ordenada = d3.sort(lista, (d) =&gt; -valor(d), (d) =&gt; d.nome);
  const top = ordenada.slice(0, 10);
  const corte = top.length ? valor(top[top.length - 1]) : 0;
  const empatadosFora = ordenada.slice(10).filter((d) =&gt; valor(d) === corte).length;
  return {top, corte, empatadosFora};
}

function ranking(itens, {valor, rotulo, dica: textoDica, cor = "var(--fm-s1)", rotuloX}) {
  return grafico({
    height: 34 * itens.length + 50, marginLeft: width &lt; 500 ? 150 : 200, marginRight: 40,
    x: {label: rotuloX, grid: true, tickFormat: (d) =&gt; (Number.isInteger(d) ? d : "")},
    y: {domain: itens.map(rotulo), label: null, tickSize: 0},
    marks: [
      Plot.barX(itens, {y: rotulo, x: valor, fill: cor, insetTop: 3, insetBottom: 3, tip: dica, title: textoDica}),
      Plot.text(itens, {y: rotulo, x: valor, text: (d) =&gt; num(valor(d)), dx: 6, textAnchor: "start", fontWeight: 600}),
      Plot.ruleX([0])
    ]
  });
}

notaEmpate = (r, unidade) =&gt; r.empatadosFora
  ? html`&lt;p class="fm-nota"&gt;${r.empatadosFora === 1 ? "Outro botonista também tem" : `Outros ${r.empatadosFora} botonistas também têm`} ${r.corte} ${unidade} e ${r.empatadosFora === 1 ? "ficou" : "ficaram"} fora da lista pela ordem alfabética.&lt;/p&gt;`
  : html``
Em 1989, 93 botonistas se reuniram em São Paulo para o primeiro Campeonato Brasileiro Individual de Futebol de Mesa na regra 12 Toques. Desde então foram 36 edições (só não houve campeonato em 2020 e 2021, por causa da pandemia); a mais recente foi a de 2026, em Campinas (SP). Esta página mostra como o campeonato mudou ao longo desses anos: quantos jogam, quantos gols saem, quem aparece mais, quem ganhou e de onde vêm os botonistas.
Use o filtro abaixo para ver tudo por categoria — ele vale para a página inteira.
{
  const pessoas = carreiras(linhasCat);
  const maxTitulos = d3.max(titulosPorBotonista, (d) =&gt; d.n);
  const maiores = titulosPorBotonista.filter((d) =&gt; d.n === maxTitulos).map((d) =&gt; d.nome);
  const anos = new Set(linhasCat.map((d) =&gt; d.ano));
  const ufs = new Set(linhasCat.map((d) =&gt; d.uf).filter((d) =&gt; d && !d.endsWith("*")));
  const kpi = (valor, rotulo, detalhe = "") =&gt; html`&lt;div class="fm-kpi"&gt;
    &lt;div class="fm-kpi-valor"&gt;${valor}&lt;/div&gt;&lt;div class="fm-kpi-rotulo"&gt;${rotulo}&lt;/div&gt;&lt;div class="fm-kpi-detalhe"&gt;${detalhe}&lt;/div&gt;&lt;/div&gt;`;
  return html`&lt;div class="fm-kpis"&gt;
    ${kpi(anos.size, "edições", `${d3.min(anos)}–${d3.max(anos)}`)}
    ${kpi(num(pessoas.length), "botonistas diferentes", "já apareceram na classificação")}
    ${kpi(ufs.size, "estados representados", "")}
    ${kpi(`${maxTitulos} títulos`, `maior campeão${variasCategorias ? " (somando categorias)" : ""}`, maiores.join(" e "))}
  &lt;/div&gt;`;
}

Participantes ano a ano

participantes = linhaDoTempo.map((e) =&gt; {
  const total = linhasCat.filter((d) =&gt; d.ano === e.ano).length;
  return {rotulo: e.rotulo, parcial: !!e.parcial, total: total || NaN, informados: e.parcial && categoria === "Todas" ? e.informados : null};
})







{
  const completos = participantes.filter((d) =&gt; !d.parcial && !isNaN(d.total));
  const parciais = participantes.filter((d) =&gt; d.parcial && !isNaN(d.total));
  const informados = participantes.filter((d) =&gt; d.informados);
  const texto = (d) =&gt; `${d.rotulo}\n${num(d.total)} botonistas na classificação${d.parcial ? "\nClassificação publicada só em parte" : ""}`;
  return grafico({
    height: 400, marginBottom: 150, marginLeft: 64, marginTop: 24,
    x: eixoEdicoes,
    y: {label: "Botonistas na classificação", grid: true, zero: true},
    marks: [
      Plot.ruleY([0]),
      Plot.line(participantes, {x: "rotulo", y: (d) =&gt; (d.parcial ? NaN : d.total), stroke: "var(--fm-s1)", strokeWidth: 2}),
      Plot.dot(completos, {x: "rotulo", y: "total", fill: "var(--fm-s1)", stroke: "var(--fm-superficie)", strokeWidth: 2, r: 4.5, tip: dica, title: texto}),
      Plot.dot(parciais, {x: "rotulo", y: "total", fill: "var(--fm-superficie)", stroke: "var(--fm-s1)", strokeWidth: 2, r: 4, tip: dica, title: texto}),
      Plot.tickY(informados, {x: "rotulo", y: "informados", stroke: "currentColor", strokeWidth: 2}),
      Plot.text(informados, {x: "rotulo", y: "informados", text: (d) =&gt; num(d.informados), dy: -8, fontWeight: 600})
    ]
  }, {largo: true});
}







html`&lt;p class="fm-nota"&gt;Mostrando ${textoCategoria}. Pontos vazados: anos em que o histórico publica só os primeiros colocados
(1991, 1992, 1993, 1994, 1996 e 1999); o número real de participantes foi maior, por isso eles ficam fora da linha.
${categoria === "Todas" ? "O traço com número é o total de participantes informado pela organização, quando existe." : ""}
Em 2020 e 2021 não houve campeonato.&lt;/p&gt;`







Seis botonistas jogaram duas categorias na mesma edição e contam uma vez em cada uma: Faoro (SP, 1997), Rogério (PR, 1998), Robertinho (PR, 2000) e Pedro (PR, 2003), no Adulto e no Sub-18; Bruno (PR, 2005) e Vinícius (SP, 2006), no Adulto e no Sub-15.

Média de gols por partida

mediaGols = linhaDoTempo.map((e) =&gt; {
  const comDados = linhasCat.filter((d) =&gt; d.ano === e.ano && d.j != null && d.gp != null);
  const jogos = d3.sum(comDados, (d) =&gt; d.j), gols = d3.sum(comDados, (d) =&gt; d.gp);
  return {rotulo: e.rotulo, gols, partidas: jogos / 2, media: jogos ? (2 * gols) / jogos : NaN};
})







grafico({
  height: 380, marginBottom: 150, marginLeft: 64, marginTop: 24,
  x: eixoAPartirDe(mediaGols.filter((d) =&gt; !isNaN(d.media)).map((d) =&gt; d.rotulo)),
  y: {label: "Gols por partida", grid: true, nice: true},
  marks: [
    Plot.line(mediaGols, {x: "rotulo", y: "media", stroke: "var(--fm-s1)", strokeWidth: 2}),
    Plot.dot(mediaGols.filter((d) =&gt; !isNaN(d.media)), {
      x: "rotulo", y: "media", fill: "var(--fm-s1)", stroke: "var(--fm-superficie)", strokeWidth: 2, r: 4.5, tip: dica,
      title: (d) =&gt; `${d.rotulo}\n${num(d.media, 2)} gols por partida\n${num(d.gols)} gols em ${num(d.partidas)} partidas`
    })
  ]
}, {largo: true})







html`&lt;p class="fm-nota"&gt;Mostrando ${textoCategoria}. O gráfico começa em 2003 porque o histórico só traz jogos e gols a partir daí; 2008 e 2009 não têm estatísticas,
e em 2005 só a categoria Adulto tem. O eixo vertical não começa no zero, para dar destaque à variação.&lt;/p&gt;`

A trajetória dos campeões

html`&lt;p&gt;Campeões da &lt;strong&gt;divisão principal&lt;/strong&gt; (Série Ouro / 1ª Divisão) de ${textoCategoria}.
${variasCategorias ? "Os títulos de todas as categorias do filtro valem igual e são somados." : ""}&lt;/p&gt;`







campeoes = linhasCat
  .filter((d) =&gt; d.niv === 1 && d.pos === 1)
  .map((d) =&gt; ({
    ...d,
    rotulo: edicaoDoAno.get(d.ano).rotulo,
    aprov: d.j && d.pts != null ? d.pts / (3 * d.j) : NaN,
    gpj: d.j && d.gp != null ? d.gp / d.j : NaN,
    sgj: d.j && d.gp != null ? (d.gp - d.gc) / d.j : NaN
  }))

titulosPorBotonista = d3.rollups(campeoes, (v) =&gt; ({
  id: v[0].id, nome: v[0].nome, ufo: v[0].ufo, n: v.length,
  detalhe: d3.groups(v, (d) =&gt; d.cat).map(([cat, t]) =&gt; `${cat}: ${t.map((d) =&gt; d.ano).join(", ")}`)
}), (d) =&gt; d.id).map((d) =&gt; d[1])

rankingTitulos = top10(titulosPorBotonista, (d) =&gt; d.n)























Quem mais venceu

ranking(rankingTitulos.top, {
  valor: (d) =&gt; d.n, rotulo: rotuloBotonista, rotuloX: "Títulos", cor: "var(--fm-s4)",
  dica: (d) =&gt; `${rotuloBotonista(d)}\n${d.n} ${d.n === 1 ? "título" : "títulos"}\n${d.detalhe.join("\n")}`
})







notaEmpate(rankingTitulos, rankingTitulos.corte === 1 ? "título" : "títulos")








A campanha do campeão, ano a ano


viewof indicador = Inputs.radio(
  new Map([["Aproveitamento", "aprov"], ["Gols pró por jogo", "gpj"], ["Saldo de gols por jogo", "sgj"]]),
  {label: "Indicador", value: "aprov"}
)








{
  const comDados = campeoes.filter((d) =&gt; !isNaN(d[indicador]));
  const paineis = categorias.filter((c) =&gt; comDados.some((d) =&gt; d.cat === c));
  const formato = indicador === "aprov" ? pct : (x) =&gt; num(x, 2);
  const nomeIndicador = {aprov: "Aproveitamento do campeão", gpj: "Gols pró por jogo do campeão", sgj: "Saldo de gols por jogo do campeão"}[indicador];
  const campanha = (d) =&gt; [d.j != null && `${d.j}J`, d.v != null && `${d.v}V`, d.d != null && `${d.d}D`].filter(Boolean).join(" ");
  return grafico({
    height: 250 * paineis.length + 170, marginBottom: 150, marginLeft: 64, marginTop: 30, marginRight: 60,
    x: eixoAPartirDe(comDados.map((d) =&gt; d.rotulo)),
    y: {label: nomeIndicador, grid: true, nice: true, zero: true, ...(indicador === "aprov" ? {percent: true, domain: [0, 100]} : {})},
    fy: {domain: paineis, label: null, padding: 0.08},
    marks: [
      Plot.ruleX(comDados, {fy: "cat", x: "rotulo", y: indicador, stroke: "var(--fm-s4)", strokeWidth: 2}),
      Plot.dot(comDados, {
        fy: "cat", x: "rotulo", y: indicador, fill: "var(--fm-s4)", stroke: "var(--fm-superficie)", strokeWidth: 2, r: 5, tip: dica,
        title: (d) =&gt; `${d.rotulo}\n${d.cat}: ${d.nome} (${d.uf ?? "sem UF"})\n${nomeIndicador}: ${formato(d[indicador])}\n${campanha(d)}\n${d.gp} gols pró, ${d.gc} gols contra`
      }),
      Plot.ruleY([0])
    ]
  }, {largo: true});
}







{
  const v = (x) =&gt; (x == null || Number.isNaN(x) ? "–" : x);
  const ordenados = d3.sort(campeoes, (d) =&gt; -d.ano, (d) =&gt; categorias.indexOf(d.cat));
  return html`&lt;div class="fm-tabela"&gt;&lt;table&gt;
    &lt;thead&gt;&lt;tr&gt;
      &lt;th class="fm-esq"&gt;Edição&lt;/th&gt;${variasCategorias ? html`&lt;th class="fm-esq"&gt;Categoria&lt;/th&gt;` : ""}&lt;th class="fm-esq"&gt;Campeão&lt;/th&gt;&lt;th class="fm-esq"&gt;UF&lt;/th&gt;
      &lt;th title="Jogos"&gt;J&lt;/th&gt;&lt;th title="Vitórias"&gt;V&lt;/th&gt;&lt;th title="Empates"&gt;E&lt;/th&gt;&lt;th title="Derrotas"&gt;D&lt;/th&gt;
      &lt;th title="Gols pró"&gt;GP&lt;/th&gt;&lt;th title="Gols contra"&gt;GC&lt;/th&gt;&lt;th title="Saldo de gols"&gt;SG&lt;/th&gt;&lt;th title="Pontos"&gt;Pts&lt;/th&gt;&lt;th&gt;Aprov.&lt;/th&gt;
    &lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;${ordenados.map((d) =&gt; html`&lt;tr&gt;
      &lt;td class="fm-esq"&gt;${d.rotulo}&lt;/td&gt;${variasCategorias ? html`&lt;td class="fm-esq"&gt;${d.cat}&lt;/td&gt;` : ""}&lt;td class="fm-esq"&gt;${d.nome}&lt;/td&gt;&lt;td class="fm-esq"&gt;${v(d.uf)}&lt;/td&gt;
      &lt;td&gt;${v(d.j)}&lt;/td&gt;&lt;td&gt;${v(d.v)}&lt;/td&gt;&lt;td&gt;${v(d.e)}&lt;/td&gt;&lt;td&gt;${v(d.d)}&lt;/td&gt;
      &lt;td&gt;${v(d.gp)}&lt;/td&gt;&lt;td&gt;${v(d.gc)}&lt;/td&gt;&lt;td&gt;${d.gp == null ? "–" : d.gp - d.gc}&lt;/td&gt;&lt;td&gt;${v(d.pts)}&lt;/td&gt;
      &lt;td&gt;${Number.isNaN(d.aprov) ? "–" : pct(d.aprov)}&lt;/td&gt;
    &lt;/tr&gt;`)}&lt;/tbody&gt;
  &lt;/table&gt;&lt;/div&gt;`;
}







Aproveitamento = pontos ÷ (3 × jogos). Passe o mouse (ou toque) em um ponto do gráfico para ver quem foi o campeão e a campanha dele. A UF é a que o campeão defendia naquele ano. Estatísticas só existem a partir de 2002 (em 2002 sem o número de jogos; empates e derrotas a partir de 2006); 2008 e 2009 não têm estatísticas.

Os estados no Brasileiro


viewof criterioUF = Inputs.radio(
  new Map([["Estado que o botonista defendia no ano", "uf"], ["Estado de origem do botonista (estreia)", "ufo"]]),
  {label: "Considerar", value: "uf"}
)








html`&lt;p class="fm-nota"&gt;${criterioUF === "uf"
  ? "Cada participação conta para o estado que o botonista representava naquela edição."
  : "Cada participação conta para o estado pelo qual o botonista estreou no Brasileiro, mesmo que depois tenha mudado. A base não tem o estado de nascimento; a estreia é a melhor aproximação disponível."}&lt;/p&gt;`







Participantes por estado, ano a ano

{
  const dominio = [...ufsPrincipais, "Outros"];
  const cores = ["var(--fm-e1)", "var(--fm-e2)", "var(--fm-e3)", "var(--fm-e4)", "var(--fm-e5)", "var(--fm-e6)", "var(--fm-e7)", "var(--fm-e-outros)"];
  const registros = empilhar(linhasCat, (d) =&gt; (ufsPrincipais.includes(d[criterioUF]) ? d[criterioUF] : "Outros"), dominio);
  return barrasEmpilhadas(registros, dominio, cores, "Botonistas na classificação");
}







{
  const outros = d3.rollups(linhasCat.filter((d) =&gt; !ufsPrincipais.includes(d[criterioUF])), (v) =&gt; v.length, (d) =&gt; d[criterioUF] ?? "sem UF")
    .sort((a, b) =&gt; b[1] - a[1]);
  return html`&lt;p class="fm-nota"&gt;Mostrando ${textoCategoria}. “Outros” reúne ${outros.map(([uf, n]) =&gt; `${uf} (${num(n)})`).join(", ")} —
  o número entre parênteses é o total de participações em todas as edições. Barras mais claras: anos com classificação incompleta.&lt;/p&gt;`;
}








Títulos por estado, ano a ano

titulos = d3.rollups(
  campeoes,
  (v) =&gt; ({n: v.length, quem: v.map((d) =&gt; `${d.cat}: ${d.nome}`)}),
  (d) =&gt; d[criterioUF] ?? "sem UF", (d) =&gt; d.ano
).flatMap(([uf, anos]) =&gt; anos.map(([ano, t]) =&gt; ({uf, ano, rotulo: edicaoDoAno.get(ano).rotulo, ...t})))

totalTitulos = d3.rollups(titulos, (v) =&gt; d3.sum(v, (d) =&gt; d.n), (d) =&gt; d.uf).sort((a, b) =&gt; b[1] - a[1])
















{
  const rampa = ["var(--fm-q1)", "var(--fm-q2)", "var(--fm-q3)", "var(--fm-q4)", "var(--fm-q5)"];
  const maximo = Math.min(d3.max(titulos, (d) =&gt; d.n) ?? 1, 5);
  // Com no máximo um título por ano (uma só categoria) não há escala: usa-se o tom do meio.
  const faixa = (d) =&gt; (maximo === 1 ? 3 : Math.min(d.n, 5));
  const celulaTexto = (filtro, tinta) =&gt; Plot.text(titulos.filter(filtro), {x: "rotulo", y: "uf", text: (d) =&gt; d.n, fill: tinta, fontWeight: 600});
  return grafico({
    height: 30 * totalTitulos.length + 180, marginBottom: 150, marginLeft: 64, marginRight: 84, marginTop: 30,
    x: {...eixoEdicoes, padding: 0.08},
    y: {domain: totalTitulos.map((d) =&gt; d[0]), label: null, tickSize: 0, padding: 0.12},
    color: {type: "ordinal", domain: maximo === 1 ? [3] : d3.range(1, maximo + 1), range: maximo === 1 ? [rampa[2]] : rampa.slice(0, maximo),
            legend: maximo &gt; 1, tickFormat: (d) =&gt; (d === 1 ? "1 título no ano" : d === 5 ? "5 ou mais" : `${d}`)},
    marks: [
      Plot.cell(titulos, {x: "rotulo", y: "uf", fill: faixa, rx: 3, tip: dica,
        title: (d) =&gt; `${d.rotulo}\n${d.uf}: ${d.n} ${d.n === 1 ? "título" : "títulos"}\n${d.quem.join("\n")}`}),
      celulaTexto((d) =&gt; faixa(d) &lt;= 2, "var(--fm-tinta-q-baixo)"),
      celulaTexto((d) =&gt; faixa(d) &gt; 2, "var(--fm-tinta-q-alto)"),
      Plot.text(totalTitulos, {y: (d) =&gt; d[0], text: (d) =&gt; `${d[1]} no total`, frameAnchor: "right", dx: 82, textAnchor: "end", fontWeight: 600})
    ]
  }, {largo: true});
}







